select v.id, s.id, v.title, v.part, v.sort from (values
  ('physical-sciences/mechanics','physical-sciences','Mechanics',null,0),
  ('pure-mathematics/analytical-geometry','pure-mathematics','Analytical geometry','Geometry',1),
  ('pure-mathematics/equations-and-inequalities','pure-mathematics','Equations and inequalities','Algebra',2),
  ('pure-mathematics/euclidean-geometry','pure-mathematics','Euclidean geometry','Geometry',3),
  ('pure-mathematics/exponents-and-surds','pure-mathematics','Exponents and surds','Algebra',4),
  ('pure-mathematics/finance-growth-and-decay','pure-mathematics','Finance, growth and decay','Algebra',5),
  ('pure-mathematics/functions','pure-mathematics','Functions','Algebra',6),
  ('pure-mathematics/measurement-revision','pure-mathematics','Measurement (revision)','Geometry',7),
  ('pure-mathematics/number-patterns','pure-mathematics','Number patterns','Algebra',8),
  ('pure-mathematics/probability','pure-mathematics','Probability','Algebra',9),
  ('pure-mathematics/revision-algebra','pure-mathematics','Revision: Algebra','Algebra',10),
  ('pure-mathematics/revision-trigonometry','pure-mathematics','Revision: Trigonometry','Geometry',11),
  ('pure-mathematics/statistics','pure-mathematics','Statistics','Geometry',12),
  ('pure-mathematics/trigonometry-identities-reduction-formulae-and-equations','pure-mathematics','Trigonometry: identities, reduction formulae and equations','Geometry',13),
  ('pure-mathematics/trigonometry-sine-cosine-and-area-rules','pure-mathematics','Trigonometry: sine, cosine and area rules','Geometry',14)
) as v(id, slug, title, part, sort) join public.subjects s on s.slug = v.slug
on conflict (id) do update set subject_id = excluded.subject_id, title = excluded.title, part = excluded.part, sort = excluded.sort;

on conflict (id) do update set topic_id = excluded.topic_id, title = excluded.title, sort = excluded.sort;
